const c = $input.first().json;
if ($input.all().length !== 1) throw new Error('This template accepts exactly one video per execution.');
if (typeof c.execute_paid_job !== 'boolean') throw new Error('execute_paid_job must be a JSON boolean.');
if (typeof c.source_url !== 'string' || /\s/.test(c.source_url) || !/^https:\/\/[^/?#]+(?:[/?#]|$)/i.test(c.source_url)) throw new Error('source_url must be a direct public HTTPS video URL.');
const authority = c.source_url.match(/^https:\/\/([^/?#]+)/i)[1];
if (authority.includes('@')) throw new Error('Do not put credentials in source_url.');
if (typeof c.filename !== 'string' || !/^[A-Za-z0-9._-]{1,150}$/.test(c.filename)) throw new Error('filename must be a simple filename without a path.');
if (!['all_area', 'sel_area', 'multi_area'].includes(c.mode)) throw new Error('mode must be all_area, sel_area, or multi_area.');
for (const k of ['source_width', 'source_height']) {
  if (!Number.isInteger(c[k]) || c[k] < 1) throw new Error(k + ' must be the actual positive source-video pixel dimension.');
}
const validateRect = (r) => {
  if (!r || typeof r !== 'object' || Array.isArray(r)) throw new Error('Each rectangle must be an object.');
  for (const k of ['x1', 'y1', 'x2', 'y2']) if (!Number.isInteger(r[k])) throw new Error('Rectangle coordinates must be integers.');
  if (r.x1 < 0 || r.y1 < 0 || r.x2 <= r.x1 || r.y2 <= r.y1 || r.x2 > c.source_width || r.y2 > c.source_height) throw new Error('Rectangle must fit inside the original source frame.');
};
let rect = c.rect;
if (c.mode === 'all_area') {
  if (rect !== null) throw new Error('Set rect to null for all_area.');
} else if (c.mode === 'sel_area') {
  validateRect(rect);
  if ((rect.x2 - rect.x1) * (rect.y2 - rect.y1) > c.source_width * c.source_height / 2) throw new Error('sel_area may cover at most half the source frame.');
} else {
  if (!Array.isArray(rect) || rect.length < 1 || rect.length > 3) throw new Error('multi_area requires 1 to 3 rectangles.');
  rect.forEach(validateRect);
  for (let i = 0; i < rect.length; i++) for (let j = i + 1; j < rect.length; j++) {
    const a = rect[i], b = rect[j];
    if (Math.max(a.x1, b.x1) < Math.min(a.x2, b.x2) && Math.max(a.y1, b.y1) < Math.min(a.y2, b.y2)) throw new Error('multi_area rectangles must not overlap.');
  }
}
for (const k of ['upload_max_polls', 'job_max_polls']) {
  if (!Number.isInteger(c[k]) || c[k] < 1 || c[k] > 1000) throw new Error(k + ' must be an integer from 1 to 1000.');
}
for (const k of ['upload_timeout_seconds', 'job_timeout_seconds']) {
  if (!Number.isInteger(c[k]) || c[k] < 5 || c[k] > 7200) throw new Error(k + ' must be an integer from 5 to 7200.');
}
if (typeof c.request_key !== 'string' || !/^[A-Za-z0-9._-]{1,200}$/.test(c.request_key)) throw new Error('request_key must contain 1 to 200 letters, digits, dots, underscores, or hyphens.');
if (c.execute_paid_job && c.request_key.startsWith('CHANGE_ME')) throw new Error('Before a paid run, set request_key to a unique stable identifier for this exact video and settings.');
return [{json: {...c, rect, upload_key: c.request_key + ':upload', job_key: c.request_key + ':remove-text'}}];

const c = $input.first().json;
return [{json: {
  status: 'preview_only',
  api_requests_made: 0,
  source_url: c.source_url,
  url_import: {method: 'POST', endpoint: 'https://api.unmarkai.net/v1/url-uploads', body: {source_url: c.source_url, filename: c.filename}},
  remove_text: {method: 'POST', endpoint: 'https://api.unmarkai.net/v1/jobs', body: {type: 'remove_text', input: {upload_id: '<returned after URL import>'}, mode: c.mode, rect: c.rect}},
  next_step: 'Review settings, current API wallet rates, and permission to edit the video. Select a secure Header Auth credential on all four HTTP nodes. Set a new stable request_key and execute_paid_job=true only when ready for a billed job.',
  reference_case: 'https://unmarkai.net/examples/remove-text-from-video/tutorial-captions/'
}}];

const r = $input.first().json;
if (typeof r.upload_id !== 'string' || !/^[A-Za-z0-9_-]+$/.test(r.upload_id)) throw new Error('URL import did not return a valid upload_id. Inspect the HTTP result; do not create another import blindly.');
return [{json: {upload_id: r.upload_id, started_at_ms: Date.now()}}];

const r = $input.first().json;
const c = $('Validate Settings').first(0, 0).json;
const state = $('Keep Upload ID').first(0, 0).json;
const polls = $runIndex + 1;
const status = r.status;
if (!['pending', 'importing', 'uploaded', 'failed', 'expired'].includes(status)) throw new Error('Unrecognized upload status; inspect Get Upload response before continuing.');
if (status === 'failed' || status === 'expired') throw new Error('Upload ' + state.upload_id + ' is ' + status + '. No remove_text job was created. Inspect Get Upload for details.');
const done = status === 'uploaded';
const elapsed = Math.max(0, (Date.now() - state.started_at_ms) / 1000);
if (!done && (polls >= c.upload_max_polls || elapsed >= c.upload_timeout_seconds)) throw new Error('Upload polling limit reached for ' + state.upload_id + '. No remove_text job was created. The remote import may still be running; inspect this upload before retrying.');
const wait_seconds = Math.max(2, Math.min(5 * Math.pow(2, Math.floor($runIndex / 6)), 30, c.upload_timeout_seconds - elapsed));
return [{json: {upload_id: state.upload_id, status, upload_ready: done, poll_count: polls, wait_seconds}}];

const c = $('Validate Settings').first(0, 0).json;
const r = $input.first().json;
if (c.execute_paid_job !== true || r.upload_ready !== true || r.status !== 'uploaded') throw new Error('Paid processing requires explicit opt-in and a completed upload.');
return [{json: {type: 'remove_text', input: {upload_id: r.upload_id}, mode: c.mode, rect: c.rect}}];

const r = $input.first().json;
if (typeof r.id !== 'string' || !/^[A-Za-z0-9_-]+$/.test(r.id)) throw new Error('Create Job did not return a valid id. A paid job may exist. Inspect the API console and preserve the original Idempotency-Key before any retry.');
return [{json: {job_id: r.id, started_at_ms: Date.now()}}];

const r = $input.first().json;
const c = $('Validate Settings').first(0, 0).json;
const state = $('Keep Job ID').first(0, 0).json;
const polls = $runIndex + 1;
const status = r.status;
if (!['validating', 'queued', 'processing', 'succeeded', 'failed', 'canceled'].includes(status)) throw new Error('Unrecognized job status for ' + state.job_id + '. Inspect Get Job; do not create a replacement job blindly.');
if (r.id !== state.job_id) throw new Error('Job response id does not match the job created in this execution.');
if (status === 'failed' || status === 'canceled') throw new Error('Job ' + state.job_id + ' is ' + status + '. Inspect Get Job for its error and billing details.');
const done = status === 'succeeded';
if (done && (typeof r.result?.url !== 'string' || !r.result.url.startsWith('https://'))) throw new Error('Job succeeded but has no valid result.url. Re-read the same job; its result may have expired. Do not create a new paid job merely to refresh a URL.');
const elapsed = Math.max(0, (Date.now() - state.started_at_ms) / 1000);
if (!done && (polls >= c.job_max_polls || elapsed >= c.job_timeout_seconds)) throw new Error('Job polling limit reached for ' + state.job_id + '. Only local waiting stopped: the remote job may still finish and be billed. Continue with GET /v1/jobs/' + state.job_id + '; do not restart paid processing.');
const wait_seconds = Math.max(2, Math.min(5 * Math.pow(2, Math.floor($runIndex / 6)), 30, c.job_timeout_seconds - elapsed));
return [{json: {...r, job_id: state.job_id, job_complete: done, poll_count: polls, wait_seconds}}];

const r = $input.first().json;
const c = $('Validate Settings').first(0, 0).json;
return [{json: {
  status: r.status,
  job_id: r.job_id,
  upload_id: $('Keep Upload ID').first(0, 0).json.upload_id,
  mode: c.mode,
  result_url: r.result.url,
  result: r.result,
  request_key: c.request_key,
  job_idempotency_key: c.job_key,
  next_step: 'Download the result before the signed link expires. Compare the entire video with the input at normal speed, especially text changes, motion, edges, faces, and background texture. Store your approved output in durable storage.',
  url_notice: 'This is a temporary signed URL, not permanent hosting. GET the same job to refresh it while results remain available. Treat execution output as private.'
}}];
